import json
answer = {"action":"submit", "grid":out}
print(json.dumps(answer, separators=(',',':')))

def halo(inp):
 h,w=len(inp),len(inp[0]); o=[r[:] for r in inp]
 for i in range(h):
  for j in range(w):
   if inp[i][j]==8:
    if i==0 or j==0 or i==h-1 or j==w-1 or any(0<=i+di<h and 0<=j+dj<w and inp[i+di][j+dj]==1 for di in (-1,0,1) for dj in (-1,0,1) if di or dj): o[i][j]=7
 return o
for ix in (1,):
 pred=halo(demos[ix][0]); exp=outs[ix]
 diff=[(i,j,pred[i][j],exp[i][j]) for i in range(len(exp)) for j in range(len(exp[0])) if pred[i][j]!=exp[i][j]]
 print('demo2 diff',len(diff),diff[:20])

