def component_mask(grid,start, color=None, conn=4):
 g=np.array(grid); h,w=g.shape; sy,sx=start
 val=g[sy,sx] if color is None else color
 out=np.zeros((h,w),bool); q=[(sy,sx)]; out[sy,sx]=True
 dirs=[(-1,0),(1,0),(0,-1),(0,1)] if conn==4 else [(di,dj) for di in(-1,0,1) for dj in(-1,0,1) if di or dj]
 while q:
  i,j=q.pop()
  for di,dj in dirs:
   a,b=i+di,j+dj
   if 0<=a<h and 0<=b<w and not out[a,b] and g[a,b]==val:
    out[a,b]=True;q.append((a,b))
 return out
